/**
 * Temporary runner for PptxDecypher
 * Usage: node tmp_rovodev_run_decypher.mjs <input.pptx>
 */

import * as fs from 'fs'
import * as path from 'path'
import * as crypto from 'crypto'
import JSZip from 'jszip'
import { DOMParser } from '@xmldom/xmldom'
import { createRequire } from 'module'
import { fileURLToPath } from 'url'
import { importedPlaceholderRoleFromNative, publicPlaceholderBindingFromNative } from './betterpptx-mcp/layout-placeholder-variants-contract.mjs'
import { normalizeCustomShows, normalizeInteractiveActions } from './betterpptx-mcp/interactive-actions-contract.mjs'

// Load PRESET_ID_MAP from auto-generated dist/preset-id-map.json (single source of truth)
// This is generated by `node src/gen-preset-id-map.cjs` during `gulp ship`
const _require = createRequire(import.meta.url)
const TOOL_ROOT = path.dirname(fileURLToPath(import.meta.url))
const _presetIdMapPath = new URL('dist/preset-id-map.json', import.meta.url).pathname.replace(/^\/([A-Z]:)/, '$1')
const _subtypeDirectionMapPath = new URL('dist/subtype-direction-map.json', import.meta.url).pathname.replace(/^\/([A-Z]:)/, '$1')
const _defaultDurationMapPath = new URL('dist/default-duration-map.json', import.meta.url).pathname.replace(/^\/([A-Z]:)/, '$1')

// ============================================================
// XML PARSING UTILITIES (using proper DOM parser)
// ============================================================
const XML_NAMESPACES = {
	'a': 'http://schemas.openxmlformats.org/drawingml/2006/main',
	'p': 'http://schemas.openxmlformats.org/presentationml/2006/main',
	'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
	'c': 'http://schemas.openxmlformats.org/drawingml/2006/chart',
	'mc': 'http://schemas.openxmlformats.org/markup-compatibility/2006',
	'dgm': 'http://schemas.openxmlformats.org/drawingml/2006/diagram',
	'dsp': 'http://schemas.microsoft.com/office/drawing/2008/diagram',
	'a14': 'http://schemas.microsoft.com/office/drawing/2010/main',
	'p14': 'http://schemas.microsoft.com/office/powerpoint/2010/main',
	'thm15': 'http://schemas.microsoft.com/office/thememl/2012/main',
	'psez': 'http://schemas.microsoft.com/office/powerpoint/2016/sectionzoom',
	'psuz': 'http://schemas.microsoft.com/office/powerpoint/2016/summaryzoom',
	'adec': 'http://schemas.microsoft.com/office/drawing/2017/decorative',
}

/**
 * Parse XML string into DOM Document
 */
function parseXml(xmlString) {
	const parser = new DOMParser()
	return parser.parseFromString(xmlString, 'text/xml')
}

/**
 * Get elements by tag name with namespace handling
 * Works with both prefixed (a:off) and local names
 */
function getElementsByTagNS(parent, tagName) {
	// Handle namespaced tags like "a:off" or "p:sp"
	const colonIdx = tagName.indexOf(':')
	if (colonIdx > 0) {
		const prefix = tagName.substring(0, colonIdx)
		const localName = tagName.substring(colonIdx + 1)
		const ns = XML_NAMESPACES[prefix]
		if (ns) {
			return Array.from(parent.getElementsByTagNameNS(ns, localName))
		}
	}
	// Fallback to local name search
	return Array.from(parent.getElementsByTagName(tagName))
}

/**
 * Get first element by tag name
 */
function getElementByTagNS(parent, tagName) {
	const elements = getElementsByTagNS(parent, tagName)
	return elements.length > 0 ? elements[0] : null
}

// Native equations are carried in a14:m inside a text body. Preserve the
// Office Math payload exactly (rather than guessing a UnicodeMath/LaTeX
// translation) so an imported equation can be replayed as an editable native
// equation without losing structure.
function equationOmmlFromShape(shapeElement) {
	const marker = getElementByTagNS(shapeElement, 'a14:m')
	if (!marker) return null
	const para = getElementByTagNS(marker, 'm:oMathPara') || getElementByTagNS(marker, 'm:oMath')
	if (!para) return null
	const xml = serializeNode(para)
	return xml && xml.length <= 2 * 1024 * 1024 ? xml : null
}

function getDirectChildByLocalName(parent, localName) {
	if (!parent || !parent.childNodes) return null
	for (let i = 0; i < parent.childNodes.length; i++) {
		const child = parent.childNodes.item(i)
		if (child && child.nodeType === 1 && child.localName === localName) return child
	}
	return null
}

function parsePictureColorEndpoint(colorEl) {
	if (!colorEl) return null
	const value = getAttr(colorEl, 'val') || ''
	const transforms = {}
	for (const child of Array.from(colorEl.childNodes || [])) {
		if (!child || child.nodeType !== 1) continue
		const raw = Number(getAttr(child, 'val'))
		if (!Number.isFinite(raw)) continue
		if (child.localName === 'tint') transforms.tint = raw / 100000
		else if (child.localName === 'shade') transforms.shade = raw / 100000
		else if (child.localName === 'satMod') transforms.saturation = raw / 100000
		else if (child.localName === 'alpha') transforms.opacity = raw / 100000
	}
	if (Object.keys(transforms).length === 0) return value
	const base = colorEl.localName === 'schemeClr'
		? { scheme: value }
		: colorEl.localName === 'prstClr'
			? { preset: value }
			: { color: value }
	return { ...base, ...transforms }
}

const ARTISTIC_EFFECT_FROM_TAG = Object.freeze({
	artisticBlur: 'blur',
	brightnessContrast: 'brightnessContrast',
	artisticCement: 'cement',
	artisticChalkSketch: 'chalkSketch',
	artisticCrisscrossEtching: 'crisscrossEtching',
	artisticCutout: 'cutout',
	artisticFilmGrain: 'filmGrain',
	artisticGlass: 'glass',
	artisticGlowDiffused: 'glowDiffused',
	artisticGlowEdges: 'glowEdges',
	artisticLightScreen: 'lightScreen',
	artisticLineDrawing: 'lineDrawing',
	artisticMarker: 'marker',
	artisticMosiaicBubbles: 'mosaicBubbles',
	artisticPaintBrush: 'paintBrush',
	artisticPaintStrokes: 'paintStrokes',
	artisticPastelsSmooth: 'pastelsSmooth',
	artisticPencilGrayscale: 'pencilGrayscale',
	artisticPencilSketch: 'pencilSketch',
	artisticPhotocopy: 'photocopy',
	artisticPlasticWrap: 'plasticWrap',
	artisticTexturizer: 'texturizer',
	artisticWatercolorSponge: 'watercolorSponge',
})

const ARTISTIC_EFFECT_READBACK = Object.freeze({
	artisticBlur: [['radius', 'radius', 1]],
	brightnessContrast: [['bright', 'brightness', 100000], ['contrast', 'contrast', 100000]],
	artisticCement: [['trans', 'transparency', 100000], ['crackSpacing', 'crackSpacing', 1]],
	artisticChalkSketch: [['trans', 'transparency', 100000], ['pressure', 'pressure', 1]],
	artisticCrisscrossEtching: [['trans', 'transparency', 100000], ['pressure', 'pressure', 1]],
	artisticCutout: [['trans', 'transparency', 100000], ['numberOfShades', 'numberOfShades', 1]],
	artisticFilmGrain: [['trans', 'transparency', 100000], ['grainSize', 'grainSize', 1]],
	artisticGlass: [['trans', 'transparency', 100000], ['scaling', 'scaling', 1]],
	artisticGlowDiffused: [['trans', 'transparency', 100000], ['intensity', 'intensity', 1]],
	artisticGlowEdges: [['trans', 'transparency', 100000], ['smoothness', 'smoothness', 1]],
	artisticLightScreen: [['trans', 'transparency', 100000], ['gridSize', 'gridSize', 1]],
	artisticLineDrawing: [['trans', 'transparency', 100000], ['pencilSize', 'pencilSize', 1]],
	artisticMarker: [['trans', 'transparency', 100000], ['size', 'size', 1]],
	artisticMosiaicBubbles: [['trans', 'transparency', 100000], ['pressure', 'pressure', 1]],
	artisticPaintBrush: [['trans', 'transparency', 100000], ['brushSize', 'brushSize', 1]],
	artisticPaintStrokes: [['trans', 'transparency', 100000], ['intensity', 'intensity', 1]],
	artisticPastelsSmooth: [['trans', 'transparency', 100000], ['scaling', 'scaling', 1]],
	artisticPencilGrayscale: [['trans', 'transparency', 100000], ['pencilSize', 'pencilSize', 1]],
	artisticPencilSketch: [['trans', 'transparency', 100000], ['pressure', 'pressure', 1]],
	artisticPhotocopy: [['trans', 'transparency', 100000], ['detail', 'detail', 1]],
	artisticPlasticWrap: [['trans', 'transparency', 100000], ['smoothness', 'smoothness', 1]],
	artisticTexturizer: [['trans', 'transparency', 100000], ['scaling', 'scaling', 1]],
	artisticWatercolorSponge: [['trans', 'transparency', 100000], ['brushSize', 'brushSize', 1]],
})

function parseArtisticEffect(imgEffectEl) {
	if (!imgEffectEl) return null
	const effectEl = Array.from(imgEffectEl.childNodes || []).find(node => node && node.nodeType === 1)
	const type = effectEl ? ARTISTIC_EFFECT_FROM_TAG[effectEl.localName] : null
	if (!effectEl || !type) return null
	const result = { type }
	for (const [attribute, field, divisor] of ARTISTIC_EFFECT_READBACK[effectEl.localName] || []) {
		const present = getPresentAttr(effectEl, attribute)
		if (present === null) continue
		const value = Number(present)
		if (Number.isFinite(value)) result[field] = value / divisor
	}
	return result
}

/**
 * Get attribute value with null safety
 */
function getAttr(element, attrName) {
	return element ? element.getAttribute(attrName) : null
}

function getRelAttr(element, attrName) {
	if (!element) return ''
	return element.getAttributeNS(XML_NAMESPACES.r, attrName) || element.getAttribute(`r:${attrName}`) || element.getAttribute(attrName) || ''
}

function getPresentAttr(element, attrName) {
	if (!element || !element.hasAttribute || !element.hasAttribute(attrName)) return null
	return element.getAttribute(attrName)
}

function accessibilityOptionsFromCNvPr(cNvPr) {
	if (!cNvPr) return {}
	const title = getPresentAttr(cNvPr, 'title')
	const altText = getPresentAttr(cNvPr, 'descr')
	const decorative = getElementByTagNS(cNvPr, 'adec:decorative')
	const decorativeValue = decorative ? getPresentAttr(decorative, 'val') : null
	return {
		...(title ? { accessibilityTitle: title } : {}),
		...(altText ? { altText } : {}),
		...(decorativeValue !== null ? { isDecorative: ['1', 'true', 'on'].includes(String(decorativeValue).toLowerCase()) } : {}),
	}
}

function decypherPlaceholderRoleFromNative(nativeType) {
	if (nativeType === 'tbl') return 'table'
	return importedPlaceholderRoleFromNative(nativeType)
}

function decypherPlaceholderBindingFromNative(native = {}) {
	const binding = publicPlaceholderBindingFromNative(native)
	if (!binding) return undefined
	return native.phType === 'tbl' && binding.type === 'tbl'
		? { ...binding, type: 'table' }
		: binding
}

function placeholderMetadataFromElement(ph) {
	if (!ph) return null
	const phType = getPresentAttr(ph, 'type') || undefined
	const rawIdx = getPresentAttr(ph, 'idx')
	const rawSize = getPresentAttr(ph, 'sz')
	const rawOrient = getPresentAttr(ph, 'orient')
	const rawCustomPrompt = getPresentAttr(ph, 'hasCustomPrompt')
	const phIdx = rawIdx !== null ? Number(rawIdx) : (phType ? 0 : undefined)
	const phSz = rawSize || undefined
	const phOrient = phType === 'clipArt' ? undefined : (rawOrient || undefined)
	const phHasCustomPrompt = rawCustomPrompt !== null
		? ['1', 'true', 'on'].includes(String(rawCustomPrompt).toLowerCase())
		: (phType ? false : undefined)
	const hasBarePh = !phType && rawIdx === null && !phSz && !phOrient && rawCustomPrompt === null
	const native = {
		...(phType ? { phType } : {}),
		...(Number.isInteger(phIdx) ? { phIdx } : {}),
		...(phSz ? { phSz } : {}),
		...(phOrient ? { phOrient } : {}),
		...(phHasCustomPrompt !== undefined ? { phHasCustomPrompt } : {}),
		...(hasBarePh ? { hasBarePh: true } : {}),
	}
	return {
		...native,
		...(phType ? { importedPlaceholderRole: decypherPlaceholderRoleFromNative(phType) } : {}),
		placeholderBinding: decypherPlaceholderBindingFromNative(native),
	}
}

function placeholderMetadataByShapeId(spTreeEl) {
	const result = new Map()
	if (!spTreeEl) return result
	for (const ph of findAllElements(spTreeEl, 'p:ph')) {
		const nvPr = ph.parentNode
		const nonVisualContainer = nvPr?.parentNode
		if (!nvPr || nvPr.localName !== 'nvPr' || !nonVisualContainer) continue
		const cNvPr = getDirectChildByLocalName(nonVisualContainer, 'cNvPr')
		const shapeId = Number(getAttr(cNvPr, 'id'))
		if (!Number.isInteger(shapeId)) continue
		const metadata = placeholderMetadataFromElement(ph)
		if (metadata) result.set(shapeId, metadata)
	}
	return result
}

function attachCanonicalPlaceholderMetadata(shape, metadata) {
	if (!shape || !metadata) return shape
	for (const key of ['phType', 'phIdx', 'phSz', 'phOrient', 'phHasCustomPrompt', 'hasBarePh']) {
		if (metadata[key] !== undefined) shape[key] = metadata[key]
	}
	if (metadata.importedPlaceholderRole) {
		shape.importedPlaceholderRole = metadata.importedPlaceholderRole
		shape.options = { ...(shape.options || {}), importedPlaceholderRole: metadata.importedPlaceholderRole }
	}
	if (metadata.placeholderBinding) {
		shape.placeholderBinding = metadata.placeholderBinding
		shape.options = { ...(shape.options || {}), placeholderBinding: metadata.placeholderBinding }
	}
	return shape
}

function escapeXmlAttrValue(value) {
	return String(value ?? '')
		.split('&').join('&amp;')
		.split('"').join('&quot;')
		.split('<').join('&lt;')
		.split('>').join('&gt;')
}

function collectXmlAttrs(element, names = null) {
	if (!element || !element.attributes) return ''
	const wanted = names ? new Set(names) : null
	const parts = []
	for (let i = 0; i < element.attributes.length; i++) {
		const attr = element.attributes[i]
		if (!attr || !attr.name || attr.name.indexOf('xmlns') === 0) continue
		if (wanted && !wanted.has(attr.name)) continue
		parts.push(`${attr.name}="${escapeXmlAttrValue(attr.value)}"`)
	}
	return parts.length > 0 ? ' ' + parts.join(' ') : ''
}

function serializeXmlNode(node) {
	if (!node) return ''
	if (node.nodeType === 3) return (node.nodeValue || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
	if (node.nodeType !== 1) return ''
	const tag = node.tagName || node.nodeName
	let attrs = ''
	if (node.attributes) {
		for (let i = 0; i < node.attributes.length; i++) {
			const a = node.attributes[i]
			attrs += ` ${a.name}="${(a.value||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;')}"`
		}
	}
	const children = node.childNodes ? Array.from(node.childNodes).map(serializeXmlNode).join('') : ''
	return `<${tag}${attrs}>${children}</${tag}>`
}

function parseRelationshipsXml(relsXml) {
	if (!relsXml) return []
	const doc = parseXml(relsXml)
	return findAllElements(doc, 'Relationship').map(rel => ({
		id: getAttr(rel, 'Id') || '',
		type: getAttr(rel, 'Type') || '',
		target: getAttr(rel, 'Target') || '',
		targetMode: getAttr(rel, 'TargetMode') || ''
	})).filter(rel => rel.id && rel.type && rel.target)
}

function parseContentTypesXml(contentTypesXml) {
	const defaults = new Map()
	const overrides = new Map()
	if (!contentTypesXml) return { defaults, overrides }
	const doc = parseXml(contentTypesXml)
	for (const def of findAllElements(doc, 'Default')) {
		const extension = (getAttr(def, 'Extension') || '').toLowerCase()
		const contentType = getAttr(def, 'ContentType') || ''
		if (extension && contentType) defaults.set(extension, contentType)
	}
	for (const over of findAllElements(doc, 'Override')) {
		let partName = getAttr(over, 'PartName') || ''
		const contentType = getAttr(over, 'ContentType') || ''
		while (partName.startsWith('/')) partName = partName.substring(1)
		if (partName && contentType) overrides.set(partName, contentType)
	}
	return { defaults, overrides }
}

function textContentFromNode(node) {
	return findAllElements(node, 'a:t').map(t => t.textContent || '').join('')
}

function parseSmartArtDataModel(dataXml) {
	const dataDoc = parseXml(dataXml || '')
	const points = findAllElements(dataDoc, 'dgm:pt')
	const docPoint = points.find(pt => getAttr(pt, 'type') === 'doc') || null
	const docPr = docPoint ? getElementByTagNS(docPoint, 'dgm:prSet') : null
	const docId = docPoint ? getAttr(docPoint, 'modelId') || '' : ''
	const textById = new Map()
	const semanticById = new Map()
	const orderedNodeIds = []
	for (const pt of points) {
		const type = getAttr(pt, 'type')
		if (type) continue
		const modelId = getAttr(pt, 'modelId') || ''
		const text = textContentFromNode(pt)
		if (!modelId) continue
		const prSet = getElementByTagNS(pt, 'dgm:prSet')
		const textColor = getElementByTagNS(pt, 'a:srgbClr')
		const image = getElementByTagNS(pt, 'a:blip')
		const role = getAttr(pt, 'type') || getAttr(prSet, 'role') || getAttr(prSet, 'nodeType') || ''
		const semantic = {}
		if (text) semantic.text = text
		if (role === 'asst' || role === 'assistant') semantic.role = 'assistant'
		else if (role && ['root', 'manager', 'member', 'peer', 'node', 'image', 'caption'].includes(role)) semantic.role = role
		if (textColor) semantic.color = getAttr(textColor, 'val') || ''
		if (image) semantic.imageRelId = getAttr(image, 'r:embed') || getAttr(image, 'embed') || ''
		textById.set(modelId, text)
		semanticById.set(modelId, semantic)
		orderedNodeIds.push(modelId)
	}
	const childrenByParent = new Map()
	const addChild = (parentId, child) => {
		const key = parentId || docId || '__root__'
		if (!childrenByParent.has(key)) childrenByParent.set(key, [])
		childrenByParent.get(key).push(child)
	}
	for (const cxn of findAllElements(dataDoc, 'dgm:cxn')) {
		if (getAttr(cxn, 'type')) continue
		const destId = getAttr(cxn, 'destId') || ''
		if (!textById.has(destId)) continue
		const srcId = getAttr(cxn, 'srcId') || ''
		addChild(srcId || docId, {
			id: destId,
			order: parseInt(getAttr(cxn, 'srcOrd') || `${orderedNodeIds.indexOf(destId)}`),
		})
	}
	for (const children of childrenByParent.values()) children.sort((a, b) => a.order - b.order)
	const visited = new Set()
	const buildNode = (nodeId) => {
		visited.add(nodeId)
		const children = (childrenByParent.get(nodeId) || [])
			.filter(child => textById.has(child.id) && !visited.has(child.id))
			.map(child => buildNode(child.id))
		const node = { ...(semanticById.get(nodeId) || {}) }
		if (node.imageRelId) node.image = node.imageRelId
		delete node.imageRelId
		if (!node.text) delete node.text
		if (children.length > 0) node.children = children
		return node
	}
	const rootChildren = childrenByParent.get(docId) || childrenByParent.get('__root__') || []
	let nodes = rootChildren.filter(child => textById.has(child.id)).map(child => buildNode(child.id))
	if (nodes.length === 0) nodes = orderedNodeIds.map(id => ({ text: textById.get(id) || '' }))
	const ext = findAllElements(dataDoc, 'dsp:dataModelExt')[0] || null
	return {
		layoutId: docPr ? getAttr(docPr, 'loTypeId') || '' : '',
		quickStyleId: docPr ? getAttr(docPr, 'qsTypeId') || '' : '',
		colorStyleId: docPr ? getAttr(docPr, 'csTypeId') || '' : '',
		nodes,
		drawingRid: ext ? getAttr(ext, 'relId') || '' : '',
		rightToLeft: Boolean(findAllElements(dataDoc, 'dgm:dir').some(dir => getAttr(dir, 'val') === 'rev')),
	}
}

function getPartContentType(contentTypes, relativePath) {
	let normalized = relativePath || ''
	while (normalized.startsWith('/')) normalized = normalized.substring(1)
	const override = contentTypes.overrides.get(normalized)
	if (override) return { contentType: override }
	const fileName = normalized.split('/').pop() || ''
	const dotIdx = fileName.lastIndexOf('.')
	const ext = dotIdx >= 0 ? fileName.substring(dotIdx + 1).toLowerCase() : ''
	const defaultContentType = ext ? contentTypes.defaults.get(ext) : null
	return defaultContentType ? { defaultContentType } : {}
}

function isTextPackagePart(relativePath) {
	const lower = (relativePath || '').toLowerCase()
	return lower.endsWith('.xml') || lower.endsWith('.rels') || lower.endsWith('.vml')
}

/**
 * Get text content from element (automatically decodes XML entities)
 */
function getTextContent(element) {
	return element ? element.textContent : ''
}

/**
 * Find descendant element matching a path like "p:nvSpPr/p:cNvPr"
 */
function findElement(parent, path) {
	const parts = path.split('/')
	let current = parent
	for (const part of parts) {
		if (!current) return null
		current = getElementByTagNS(current, part)
	}
	return current
}

/**
 * Find all descendant elements by tag name (deep search)
 */
function findAllElements(parent, tagName) {
	return getElementsByTagNS(parent, tagName)
}

function chartTextStyleFromXml(container) {
	const defRPr = container ? findElement(container, 'a:defRPr') : null
	if (!defRPr) return null
	const rawSize = Number(defRPr.getAttribute('sz'))
	const color = findElement(defRPr, 'a:srgbClr')?.getAttribute('val') || null
	const fontFace = findElement(defRPr, 'a:latin')?.getAttribute('typeface') || null
	const booleanAttr = name => {
		const value = defRPr.getAttribute(name)
		if (value === null || value === '') return undefined
		return value === '1' || value === 'true'
	}
	return {
		...(Number.isFinite(rawSize) && rawSize > 0 ? { fontSize: rawSize / 100 } : {}),
		...(color ? { color } : {}),
		...(fontFace ? { fontFace } : {}),
		...(booleanAttr('b') !== undefined ? { bold: booleanAttr('b') } : {}),
		...(booleanAttr('i') !== undefined ? { italic: booleanAttr('i') } : {}),
	}
}

function extractChartSemanticOptions(chartDoc) {
	const options = {}
	const booleanValue = element => {
		if (!element) return undefined
		const value = element.getAttribute('val')
		if (value === null || value === '') return true
		return ['1', 'true', 'on', 'yes'].includes(value.trim().toLowerCase())
	}
	const numericValue = element => {
		if (!element) return undefined
		const raw = element.getAttribute('val')
		if (raw === null || raw === '') return undefined
		const value = Number(raw)
		return Number.isFinite(value) ? value : undefined
	}
	const richText = container => container
		? findAllElements(container, 'a:t').map(node => node.textContent || '').join('').trim()
		: ''
	const legacyStyle = findElement(chartDoc, 'c:style')
	const modernStyle = findElement(chartDoc, 'c14:style')
	const legacyStyleId = Number(legacyStyle?.getAttribute('val'))
	const modernStyleId = Number(modernStyle?.getAttribute('val'))
	if (Number.isInteger(legacyStyleId) && legacyStyleId > 0) options.chartStyleId = legacyStyleId
	if (Number.isInteger(modernStyleId) && modernStyleId > 0) options.chartStyleModernId = modernStyleId
	const dataLabelContainers = findAllElements(chartDoc, 'c:dLbls')
	if (dataLabelContainers.length > 0) {
		const showValueNodes = dataLabelContainers.map(container => findElement(container, 'c:showVal')).filter(Boolean)
		if (showValueNodes.length > 0) options.showValue = showValueNodes.some(node => booleanValue(node) === true)
		const styles = dataLabelContainers.map(chartTextStyleFromXml).filter(Boolean)
		const sizes = styles.map(style => style.fontSize).filter(value => Number.isFinite(value) && value > 0)
		if (sizes.length > 0) options.dataLabelFontSize = Math.min(...sizes)
		const style = styles.find(item => item.color || item.fontFace || item.bold !== undefined || item.italic !== undefined)
		if (style?.color) options.dataLabelColor = style.color
		if (style?.fontFace) options.dataLabelFontFace = style.fontFace
		if (style?.bold !== undefined) options.dataLabelFontBold = style.bold
		if (style?.italic !== undefined) options.dataLabelFontItalic = style.italic
		for (const [tag, field] of [
			['c:showCatName', 'showLabel'],
			['c:showSerName', 'showSerName'],
			['c:showPercent', 'showPercent'],
			['c:showLeaderLines', 'showLeaderLines'],
		]) {
			const nodes = dataLabelContainers.map(container => findElement(container, tag)).filter(Boolean)
			if (nodes.length > 0) options[field] = nodes.some(node => booleanValue(node) === true)
		}
		const formatCode = dataLabelContainers.map(container => findElement(container, 'c:numFmt')?.getAttribute('formatCode')).find(Boolean)
		if (formatCode) options.dataLabelFormatCode = formatCode
		const labelPosition = dataLabelContainers.map(container => findElement(container, 'c:dLblPos')?.getAttribute('val')).find(Boolean)
		if (['b', 'bestFit', 'ctr', 'l', 'r', 't', 'inEnd', 'outEnd'].includes(labelPosition)) options.dataLabelPosition = labelPosition
	}
	const applyAxis = (axis, prefix) => {
		if (!axis) return
		const deleted = findElement(axis, 'c:delete')
		if (deleted) options[`${prefix}Hidden`] = booleanValue(deleted) === true
		const style = chartTextStyleFromXml(findElement(axis, 'c:txPr'))
		if (style) {
			if (style.fontSize) options[`${prefix}LabelFontSize`] = style.fontSize
			if (style.color) options[`${prefix}LabelColor`] = style.color
			if (style.fontFace) options[`${prefix}LabelFontFace`] = style.fontFace
			if (style.bold !== undefined) options[`${prefix}LabelFontBold`] = style.bold
			if (style.italic !== undefined) options[`${prefix}LabelFontItalic`] = style.italic
		}
		const numberFormat = findElement(axis, 'c:numFmt')?.getAttribute('formatCode')
		if (numberFormat) options[prefix === 'valAxis' ? 'valAxisLabelFormatCode' : `${prefix.replace('Axis', '')}LabelFormatCode`] = numberFormat
		const labelPosition = findElement(axis, 'c:tickLblPos')?.getAttribute('val')
		if (['none', 'low', 'high', 'nextTo'].includes(labelPosition)) options[`${prefix}LabelPos`] = labelPosition
		for (const [tag, suffix] of [['c:majorUnit', 'MajorUnit'], ['c:minorUnit', 'MinorUnit']]) {
			const value = numericValue(findElement(axis, tag))
			if (value !== undefined) options[`${prefix}${suffix}`] = value
		}
		if (prefix !== 'serAxis') {
			const scaling = findElement(axis, 'c:scaling')
			for (const [tag, suffix] of [['c:min', 'MinVal'], ['c:max', 'MaxVal']]) {
				const value = numericValue(scaling ? findElement(scaling, tag) : null)
				if (value !== undefined) options[`${prefix}${suffix}`] = value
			}
		}
		const axisTitle = richText(findElement(axis, 'c:title'))
		if (axisTitle) {
			options[`show${prefix[0].toUpperCase()}${prefix.slice(1)}Title`] = true
			options[`${prefix}Title`] = axisTitle
		}
		options[prefix === 'catAxis' ? 'catGridLine' : prefix === 'valAxis' ? 'valGridLine' : 'serGridLine'] = {
			style: findElement(axis, 'c:majorGridlines') ? 'solid' : 'none',
		}
	}
	const plotArea = findElement(chartDoc, 'c:chartSpace/c:chart/c:plotArea')
	applyAxis(plotArea ? findElement(plotArea, 'c:catAx') : null, 'catAxis')
	applyAxis(plotArea ? findElement(plotArea, 'c:valAx') : null, 'valAxis')
	applyAxis(plotArea ? findElement(plotArea, 'c:serAx') : null, 'serAxis')
	const manualLayout = plotArea ? findElement(plotArea, 'c:layout/c:manualLayout') : null
	if (manualLayout) {
		const layout = {}
		for (const field of ['x', 'y', 'w', 'h']) {
			const value = numericValue(findElement(manualLayout, `c:${field}`))
			if (value !== undefined) layout[field] = value
		}
		if (Object.keys(layout).length > 0) options.layout = layout
	}
	const dataTable = plotArea ? findElement(plotArea, 'c:dTable') : null
	if (dataTable) {
		options.showDataTable = true
		for (const [tag, field] of [
			['c:showHorzBorder', 'showDataTableHorzBorder'],
			['c:showVertBorder', 'showDataTableVertBorder'],
			['c:showOutline', 'showDataTableOutline'],
			['c:showKeys', 'showDataTableKeys'],
		]) {
			const value = booleanValue(findElement(dataTable, tag))
			if (value !== undefined) options[field] = value
		}
	}
	const legend = findElement(chartDoc, 'c:chartSpace/c:chart/c:legend')
	if (legend) {
		const deleted = findElement(legend, 'c:delete')
		options.showLegend = !deleted || deleted.getAttribute('val') !== '1'
		const style = chartTextStyleFromXml(findElement(legend, 'c:txPr'))
		if (style?.fontSize) options.legendFontSize = style.fontSize
		if (style?.color) options.legendColor = style.color
		if (style?.fontFace) options.legendFontFace = style.fontFace
		const position = findElement(legend, 'c:legendPos')?.getAttribute('val')
		if (['b', 'l', 'r', 't', 'tr'].includes(position)) options.legendPos = position
	} else options.showLegend = false
	const title = findElement(chartDoc, 'c:chartSpace/c:chart/c:title')
	if (title) {
		options.showTitle = true
		const text = richText(title)
		if (text) options.title = text
		const style = chartTextStyleFromXml(findElement(title, 'c:txPr'))
		if (style?.fontSize) options.titleFontSize = style.fontSize
		if (style?.color) options.titleColor = style.color
		if (style?.fontFace) options.titleFontFace = style.fontFace
		if (style?.bold !== undefined) options.titleBold = style.bold
	} else options.showTitle = false
	const displayBlanksAs = findElement(chartDoc, 'c:chartSpace/c:chart/c:dispBlanksAs')?.getAttribute('val')
	if (displayBlanksAs) options.displayBlanksAs = displayBlanksAs
	return options
}

function legacyChartTypeFromXml(chartDoc) {
	const plotArea = findElement(chartDoc, 'c:chartSpace/c:chart/c:plotArea')
	if (!plotArea) return 'bar'
	for (const [tag, type] of [
		['c:bar3DChart', 'bar3D'],
		['c:barChart', 'bar'],
		['c:bubbleChart', 'bubble'],
		['c:doughnutChart', 'doughnut'],
		['c:lineChart', 'line'],
		['c:pieChart', 'pie'],
		['c:radarChart', 'radar'],
		['c:scatterChart', 'scatter'],
		['c:areaChart', 'area'],
	]) {
		const chart = findElement(plotArea, tag)
		if (!chart) continue
		if (type === 'bubble') {
			const bubble3D = findElement(chart, 'c:bubble3D')
			const value = bubble3D?.getAttribute('val')
			if (value === '1' || value === 'true') return 'bubble3D'
		}
		return type
	}
	return 'bar'
}

function chartColorStyleIdFromXml(xml) {
	if (!xml) return undefined
	const document = parseXml(xml)
	const root = document?.documentElement
	const id = Number(root?.getAttribute('id'))
	return Number.isInteger(id) && id > 0 ? id : undefined
}

function extractTableSemanticOptions(tblPrEl) {
	if (!tblPrEl) return { options: {}, requiresRaw: false }
	const options = {}
	const flagMap = new Map([
		['firstRow', 'headerRow'],
		['lastRow', 'totalRow'],
		['firstCol', 'firstColumn'],
		['lastCol', 'lastColumn'],
		['bandRow', 'bandedRows'],
		['bandCol', 'bandedColumns'],
	])
	let requiresRaw = false
	for (let index = 0; index < tblPrEl.attributes.length; index++) {
		const attribute = tblPrEl.attributes.item(index)
		if (!attribute) continue
		const semanticName = flagMap.get(attribute.localName || attribute.name)
		if (!semanticName) {
			requiresRaw = true
			continue
		}
		const value = String(attribute.value || '').trim().toLowerCase()
		if (['1', 'true', 'on', 'yes'].includes(value)) options[semanticName] = true
		else if (['0', 'false', 'off', 'no'].includes(value)) options[semanticName] = false
		else requiresRaw = true
	}
	for (const child of Array.from(tblPrEl.childNodes || [])) {
		if (!child || child.nodeType !== 1) continue
		if (child.localName !== 'tableStyleId') {
			requiresRaw = true
			continue
		}
		const styleId = String(child.textContent || '').trim()
		if (styleId) options.tableStyleId = styleId
		if (child.attributes?.length > 0 || Array.from(child.childNodes || []).some(node => node?.nodeType === 1)) requiresRaw = true
	}
	return { options, requiresRaw }
}

function hasDescendantElement(parent, namespaceUri, localName) {
	if (!parent || !parent.getElementsByTagNameNS) return false
	return parent.getElementsByTagNameNS(namespaceUri, localName).length > 0
}

// ============================================================
// CONFIGURATION
// ============================================================
function parseCliArgs(argv) {
	const options = {
		inputPath: '',
		outputDir: './decyphered',
		autoRegenerate: true,
		jsonSummaryPath: '',
		jsonModelPath: '',
		showHelp: false,
	}
	for (let i = 0; i < argv.length; i++) {
		const arg = argv[i]
		if (arg === '--help' || arg === '-h') {
			options.showHelp = true
		} else if (arg === '--output' || arg === '-o') {
			options.outputDir = argv[++i] || options.outputDir
		} else if (arg === '--no-regenerate') {
			options.autoRegenerate = false
		} else if (arg === '--json-summary') {
			options.jsonSummaryPath = argv[++i] || ''
		} else if (arg === '--json-model') {
			options.jsonModelPath = argv[++i] || ''
		} else if (!arg.startsWith('-') && !options.inputPath) {
			options.inputPath = arg
		}
	}
	return options
}

function printUsage() {
	console.log(`Usage: node PPTX_ULTIMATE_DECYPHER_TOOL.mjs <input.pptx> [options]

Options:
  --output, -o <dir>       Output directory (default: ./decyphered)
  --no-regenerate          Generate generator.mjs without running it
  --json-summary <path>    Write machine-readable result summary
  --json-model <path>      Write private PresentationModel JSON for MCP import
  --help, -h               Show this help message`)
}

const CLI_OPTIONS = parseCliArgs(process.argv.slice(2))
const INPUT_PATH = CLI_OPTIONS.inputPath
const OUTPUT_DIR = CLI_OPTIONS.outputDir

if (CLI_OPTIONS.showHelp || !INPUT_PATH) {
	printUsage()
	process.exit(CLI_OPTIONS.showHelp ? 0 : 1)
}

if (!fs.existsSync(INPUT_PATH)) {
	console.error(`Error: File not found: ${INPUT_PATH}`)
	process.exit(1)
}

