							if (getAttr(outerShdw, 'blurRad')) shadow.blur = emuToPoints(parseInt(getAttr(outerShdw, 'blurRad')))
							if (getAttr(outerShdw, 'dist')) shadow.offset = emuToPoints(parseInt(getAttr(outerShdw, 'dist')))
							if (getAttr(outerShdw, 'dir')) shadow.angle = Math.round(parseInt(getAttr(outerShdw, 'dir')) / 60000)
							const outerShdwColor = extractColorFromElement(outerShdw)
			shadow.color = outerShdwColor && outerShdwColor._prstClr
				? { type: 'preset', preset: outerShdwColor._prstClr }
				: outerShdwColor
							const alphaEl = getElementByTagNS(outerShdw, 'a:alpha')
