							if (getAttr(reflectionEl, 'blurRad')) reflection.blur = emuToPoints(parseInt(getAttr(reflectionEl, 'blurRad')))
							if (getAttr(reflectionEl, 'dist')) reflection.offset = emuToPoints(parseInt(getAttr(reflectionEl, 'dist')))
							if (getAttr(reflectionEl, 'stA')) reflection.opacity = parseInt(getAttr(reflectionEl, 'stA')) / 100000
							if (getAttr(reflectionEl, 'endA')) reflection.endOpacity = parseInt(getAttr(reflectionEl, 'endA')) / 100000
							if (getAttr(reflectionEl, 'endPos')) reflection.fadeEnd = parseInt(getAttr(reflectionEl, 'endPos')) / 1000
							if (getAttr(reflectionEl, 'dir')) reflection.angle = Math.round(parseInt(getAttr(reflectionEl, 'dir')) / 60000)
