									const lon = getAttr(rot, 'lon')
									const rev = getAttr(rot, 'rev')
									if (lon) effect3D.rotationX = publicCameraRotationDegrees(lon, true)
									if (lat) effect3D.rotationY = publicCameraRotationDegrees(lat)
									if (rev) effect3D.rotationZ = publicCameraRotationDegrees(rev, true)
