							const brRPr = getElementByTagNS(rEl, 'a:rPr')
							if (brRPr) {
								brProps = {}
								const brLang = getAttr(brRPr, 'lang')
								if (brLang) brProps.lang = brLang
								const brSz = getAttr(brRPr, 'sz')
								if (brSz !== null && brSz !== '') brProps.fontSize = parseInt(brSz) / 100
								const brDirty = getAttr(brRPr, 'dirty')
								if (brDirty !== null && brDirty !== '') brProps._rPrDirty = brDirty
								const brAltLang = getAttr(brRPr, 'altLang')
								if (brAltLang !== null && brAltLang !== '') brProps._rPrAltLang = brAltLang
								const brErr = getAttr(brRPr, 'err')
								if (brErr !== null && brErr !== '') brProps._rPrErr = brErr
								const brB = getAttr(brRPr, 'b')
								if (brB !== null && brB !== '') brProps._rPrB = brB
								const brU = getAttr(brRPr, 'u')
								if (brU !== null && brU !== '') brProps._rPrU = brU
								let rawBrRprXml = ''
								const brLatin = getElementByTagNS(brRPr, 'a:latin')
								const brEa = getElementByTagNS(brRPr, 'a:ea')
								const brCs = getElementByTagNS(brRPr, 'a:cs')
								const brSym = getElementByTagNS(brRPr, 'a:sym')
								function buildBrFontTag(tagName, fontEl) {
									if (!fontEl) return ''
									const attrs = []
									const tf = getAttr(fontEl, 'typeface')
									if (tf !== null) attrs.push(`typeface="${tf}"`)
									const pan = getAttr(fontEl, 'panose')
									if (pan && pan.trim()) attrs.push(`panose="${pan}"`)
									const pf = getAttr(fontEl, 'pitchFamily')
									if (pf !== null && pf !== '') attrs.push(`pitchFamily="${pf}"`)
									const cs2 = getAttr(fontEl, 'charset')
									if (cs2 !== null && cs2 !== '') attrs.push(`charset="${cs2}"`)
									if (attrs.length === 0) return ''
									return `<${tagName} ${attrs.join(' ')}/>`
								}
								if (brEa) rawBrRprXml += buildBrFontTag('a:ea', brEa)
								if (brCs) rawBrRprXml += buildBrFontTag('a:cs', brCs)
								if (brSym) rawBrRprXml += buildBrFontTag('a:sym', brSym)
								const brLn = getElementByTagNS(brRPr, 'a:ln')
								if (brLn && getElementByTagNS(brLn, 'a:noFill')) {
									rawBrRprXml += serializeNode(brLn)
								}
								const brSolid = getElementByTagNS(brRPr, 'a:solidFill')
								if (brSolid) {
									rawBrRprXml += serializeNode(brSolid)
								}
								const brEffectLst = getElementByTagNS(brRPr, 'a:effectLst')
								if (brEffectLst && Array.from(brEffectLst.childNodes || []).filter(n => n.nodeType === 1).length === 0) rawBrRprXml += '<a:effectLst/>'
								const brULnTx = getElementByTagNS(brRPr, 'a:uLnTx')
								if (brULnTx) rawBrRprXml += serializeNode(brULnTx)
								const brUFillTx = getElementByTagNS(brRPr, 'a:uFillTx')
								if (brUFillTx) rawBrRprXml += serializeNode(brUFillTx)
								const brHlinkClick = getElementByTagNS(brRPr, 'a:hlinkClick')
								if (brHlinkClick) rawBrRprXml += serializeNode(brHlinkClick)
								if (brLatin) rawBrRprXml += buildBrFontTag('a:latin', brLatin)
								if (rawBrRprXml) brProps._rawRprXml = rawBrRprXml
							}
							runs.push({ text: '\n', properties: brProps })
