			const picXml = match[0]
			const cNvPrMatch = picXml.match(/<p:cNvPr\b([^>]*)\/?>/)
			if (!cNvPrMatch) continue
			const cNvPrAttrs = parseAttributes(cNvPrMatch[1] || '')
			if (!cNvPrAttrs.id) continue
			
			const id = parseInt(cNvPrAttrs.id)
			const name = cNvPrAttrs.name || ''
			const altText = cNvPrAttrs.descr || ''

			// Skip pics inside mc:Fallback - they're handled by the mc:AlternateContent processor
			if (fallbackPicIds.has(id)) continue
			
			let x = 0, y = 0, w = 1, h = 1
			const offMatch = picXml.match(/<a:off\s+x="(-?\d+)"\s+y="(-?\d+)"/)
			if (offMatch) {
				x = emuToInches(parseInt(offMatch[1]))
				y = emuToInches(parseInt(offMatch[2]))
			}
			const extMatch = picXml.match(/<a:ext\s+cx="(\d+)"\s+cy="(\d+)"/)
			if (extMatch) {
				w = emuToInches(parseInt(extMatch[1]))
				h = emuToInches(parseInt(extMatch[2]))
			}
			
			// Get image path from relationships (relative to generator.mjs location)
			const blipMatch = picXml.match(/<a:blip\s+[^>]*r:embed="([^"]+)"/)
			// Check for video/audio file (media shapes use <p:nvPicPr> with <a:videoFile> or <a:audioFile>)
			const picXmlStr = picXml
			const hasVideoFile = picXmlStr.includes('<a:videoFile') || picXmlStr.includes('videoFile')
			const hasAudioFile = picXmlStr.includes('<a:audioFile') || picXmlStr.includes('audioFile')
			const isMedia = hasVideoFile || hasAudioFile
			let mediaType = hasVideoFile ? 'video' : hasAudioFile ? 'audio' : null
			
