						const hrid = hlinkEl ? (hlinkEl.getAttributeNS(XML_NAMESPACES.r, 'id') || hlinkEl.getAttribute('r:id') || '') : ''
						if (picActionReadback?.preservation?.click?.xml && !hrid) picRawHlinkClickXml = picActionReadback.preservation.click.xml
