						picPhIdx = getPresentAttr(phEl, 'idx')
						const phSzVal = getPresentAttr(phEl, 'sz')
						if (phSzVal) picPhSz = phSzVal
						const rawPicPhOrient = getPresentAttr(phEl, 'orient')
						picPhOrient = picPhType === 'clipArt' ? null : rawPicPhOrient
						const phCustomPromptVal = getPresentAttr(phEl, 'hasCustomPrompt')
						if (phCustomPromptVal !== null) picPhHasCustomPrompt = ['1', 'true'].includes(String(phCustomPromptVal).toLowerCase())
