						if (fillEl) picRawFillXml = serializeNode(fillEl)
						const picPrstGeom = directSpPrChild('prstGeom')
						const picCustGeom = directSpPrChild('custGeom')
						if (picPrstGeom || picCustGeom) picRawPrstGeomXml = serializeNode(picPrstGeom || picCustGeom)
						if (picPrstGeom) picPrstGeomType = getAttr(picPrstGeom, 'prst') || null
