    if (def.rotation) baseOpts.rotate = def.rotation;
    if (def.options?.rotation) baseOpts.rotate = def.options.rotation;
    if (def.options && Object.prototype.hasOwnProperty.call(def.options, 'accessibilityTitle')) baseOpts.accessibilityTitle = def.options.accessibilityTitle;
    if (def.options && Object.prototype.hasOwnProperty.call(def.options, 'altText')) baseOpts.altText = def.options.altText;
    if (def.options && Object.prototype.hasOwnProperty.call(def.options, 'isDecorative')) baseOpts.isDecorative = def.options.isDecorative;
    if (includeShapeHyperlinks && def.hyperlink) baseOpts.hyperlink = def.hyperlink;
    if (includeShapeHyperlinks && def.options?.hyperlink) baseOpts.hyperlink = def.options.hyperlink;
    if (def.flipH) baseOpts.flipH = true;
    if (def.flipV) baseOpts.flipV = true;
    if (def.options?.flipH) baseOpts.flipH = true;
    if (def.options?.flipV) baseOpts.flipV = true;
    if (def.phType) {
        baseOpts.placeholder = def.phType;
        baseOpts.phType = def.phType;
    } else if (def.phIdx !== undefined && def.phIdx !== null) {
        baseOpts.placeholder = 'body'; // idx-only placeholder = body
    }
	if (def.phIdx !== undefined && def.phIdx !== null) baseOpts.phIdx = def.phIdx;
	if (def.phSz) baseOpts.phSz = def.phSz;
	if (def.phOrient) baseOpts.phOrient = def.phOrient;
	if (def.phHasCustomPrompt !== undefined) baseOpts.phHasCustomPrompt = def.phHasCustomPrompt;
    if (def.rawShapeHlinkClickXml) baseOpts._rawShapeHlinkClickXml = def.rawShapeHlinkClickXml;
    if (def.options?._rawNvPrChildXml) baseOpts._rawNvPrChildXml = def.options._rawNvPrChildXml;
    if (def.hasBarePh) { baseOpts._barePlaceholder = true; baseOpts.hasBarePh = true; }
    if (def.options?.phType) baseOpts.placeholder = def.options.phType;
	if (def.options?.placeholderBinding) baseOpts.placeholderBinding = def.options.placeholderBinding;
	if (def.options?.importedPlaceholderRole) baseOpts.importedPlaceholderRole = def.options.importedPlaceholderRole;
