    if (def.options?._rawCNvPicPrXml) baseOpts._rawCNvPicPrXml = def.options._rawCNvPicPrXml;
    if (def.options?._rawPicSpPrXml) baseOpts._rawPicSpPrXml = def.options._rawPicSpPrXml;
    if (def.options?._rawPicPrstGeomXml) baseOpts._rawPicPrstGeomXml = def.options._rawPicPrstGeomXml;
    if (def.options?._rawSpPrExtLstXml) baseOpts._rawSpPrExtLstXml = def.options._rawSpPrExtLstXml;
